import base64,hashlib,io,zipfile,tempfile,sys
from pathlib import Path
PAYLOAD = ''
EXPECTED_SHA256 = 'fea5ad45f94ed4e65f8b4cbaf29a5d8dc060ff3e78c805c09eaf3b87a8bb5b05'
def start():
    payload=base64.b64decode(PAYLOAD)
    if hashlib.sha256(payload).hexdigest()!=EXPECTED_SHA256:raise RuntimeError("Embedded source digest mismatch")
    root=Path(tempfile.mkdtemp(prefix="gpt2_b4_full_xor_source_"))
