    for name,expected in manifest.items():
        if hashlib.sha256((root/name).read_bytes()).hexdigest()!=expected:raise RuntimeError('Source mismatch: '+name)
    paths=list(sys.path);names=['launch_b4','archive_io','protocol','process_io'];cached={n:sys.modules.pop(n) for n in names if n in sys.modules}
    sys.path.insert(0,str(root))
    try:
        from launch_b4 import start as launch
        launch(USE_GOOGLE_DRIVE,RESUME_ZIP)
    finally:
        for n in names:sys.modules.pop(n,None)
        sys.modules.update(cached);sys.path[:]=paths
